def CompactClopenNeighborhoodBasis [LocallyCompactSpace K] [T2Space K] : Prop :=
  IsScattered K → ∀ x : K, ∀ O : Set K, IsOpen O → x ∈ O →
    ∃ U : Set K, IsClopen U ∧ IsCompact U ∧ x ∈ U ∧ U ⊆ O

